import{_ as s,l as o,o as e,c as l,v as t,p as n,x as r,d as h,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"抖动","description":"","frontmatter":{"title":"抖动","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thrashing.md","filePath":"cs/thrashing.md","lastUpdated":1789023840000}'),d={name:"cs/thrashing.md"};function E(m,a,A,_,u,B){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="抖动" tabindex="-1">抖动 <a class="header-anchor" href="#抖动" aria-label="Permalink to &quot;抖动&quot;">​</a></h1><div class="epigraph"><p>系统把几乎全部时间花在换页上，吞吐接近零；再精致的 CLOCK 也救不了工作集之和大于内存。</p><footer>—— 据 Denning 对抖动的讨论；Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/working-set">上一课</a>要求驻留集盖住 W(t, Δ)。物理帧是固定的。多道一高，每个进程的窗口都装不下。<a href="/cs/scheduling-metrics">调度指标</a>上 CPU 利用率可能看起来不低——核在跑缺页处理与 I/O 等待。缺口是<strong>诊断与负荷控制</strong>：认出抖动，并减少同时驻留的工作集个数，而不是把时间片切得更碎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>置换课已警告「工作集大于内存则任何算法都会抖」。本课要回答：抖和不抖在计数器上差在哪，内核可以采取什么。缺页率高、交换设备饱和、就绪队列却空（都在等页），是典型画像。若误判为 CPU 不够而再多塞几个作业，W 之和更大。缺口不是新的页表位，而是负荷：挂起若干进程，把它们的帧交给剩下的，使留下的集合可覆盖。</p><p>本课不把 LIFO 挂起策略的全部变体写完。</p><p><span class="marginnote">中等程度的多道有一个峰值：太少则 CPU 闲，太多则抖动。工作集模型给峰值一个解释，而不是一条可移植的魔法数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监测 major 缺页与交换吞吐。超过阈值：停止接受新作业，或换出（挂起）整个进程的驻留集。恢复时按工作集再调入，避免一次只换一页地爬。PFF 若持续高，减该进程帧数会更糟，应减进程数。与实时调度对照：期限任务若因换页错过，先保证其工作集钉住，而不是提高优先级空转。</p>',9)),(e(),n(p,null,{default:r(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUM%5B%22%CE%A3%20W%20%E5%A4%A7%E4%BA%8E%E7%89%A9%E7%90%86%E5%86%85%E5%AD%98%22%5D%20--%3E%20PF%5B%22major%20%E7%BC%BA%E9%A1%B5%E9%A3%8E%E6%9A%B4%22%5D%0A%20%20PF%20--%3E%20WRONG%5B%22%E5%86%8D%E6%8F%90%E9%AB%98%E5%A4%9A%E9%81%93%3A%20%E6%9B%B4%E7%B3%9F%22%5D%0A%20%20PF%20--%3E%20SUSP%5B%22%E6%8C%82%E8%B5%B7%E9%83%A8%E5%88%86%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20SUSP%20--%3E%20FIT%5B%22%E7%95%99%E4%B8%8B%E7%9A%84%20W%20%E5%8F%AF%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>抖动说明虚存不是无限 DRAM：它把磁盘当成 Cache 的下一层，缺失代价以毫秒计。CLOCK 只决定「哪一页走」；抖动决定「有没有哪一页走了还能工作」。<a href="/cs/locality-principle">局部性</a>一旦被换页打散，引用串不再有稳定窗口。用户看见的是全机卡死，不是某一个 malloc 返回 NULL——匿名页稍后还有 OOM，本课先钉负荷。</p><p>不要把抖动写成网络安全或攻击；它是资源规划失败。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cgroup 的内存上限全文（隔离课会回来）。不把网络交换（远程页）当默认。SSD 降低了换页延迟，阈值会变，结构不变：ΣW &gt; RAM 仍抖。文件页与匿名页谁先被扔，下一课才分来源——扔掉文件页可能只是再读文件，不一定是抖动。</p><p>后课默认：负荷控制针对「页」的总量。页从哪来、扔掉是否必须写交换区，下一课匿名页对文件页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>抖动是 ΣW 超过内存；对策是减多道，不是更小时间片。</li><li>画像：高缺页、交换饱和、CPU 在等 I/O。</li><li>页的后备设备不同，淘汰代价不同，是下一课。</li><li>出处：Denning；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const S=s(d,[["render",E]]);export{P as __pageData,S as default};
